"""
Capability Matrix & Data Quality Report Module
Determines which analyses are mathematically feasible based on available canonical fields.
Follows strict graceful degradation — never fabricates missing data.
"""

from typing import Dict, Any, List

from tools.base_tool import EXTENDED_CLINICAL_FEATURES


class CapabilityMatrix:
    """
    Evaluates dataset schema and data quality to produce a machine-readable capability matrix.
    """

    def evaluate_capabilities(self, canonical_mapping: Dict[str, str], profile: Dict[str, Any]) -> Dict[str, Any]:
        """
        Evaluates which ML analysis tools can be executed on this dataset.
        """
        # Invert canonical mapping: canonical_field -> list of source column names
        canonical_to_source = {}
        for src, can in canonical_mapping.items():
            if can != "OTHER":
                canonical_to_source.setdefault(can, []).append(src)

        available_fields = list(canonical_to_source.keys())
        missing_fields = [f for f in ["DRUG", "DATE", "PATIENT_ID", "DIAGNOSIS", "AGE", "GENDER", "DOSAGE", "REGION", "QUANTITY", "PRESCRIBER", "RISK_SCORE"] if f not in available_fields]
        
        quality_warnings = []
        missing_rate = profile.get("missing_rate_pct", 0)
        if missing_rate > 15:
            quality_warnings.append(f"High overall dataset missing rate ({missing_rate}%). Certain statistical inferences may have wider confidence intervals.")
            
        row_count = profile.get("row_count", 0)
        if row_count < 30:
            quality_warnings.append(f"Small dataset size ({row_count} records). Machine learning models will employ cross-validation with regularized constraints.")

        # --- Evaluate Specific Capabilities ---
        capabilities = {}

        # 1. Trend & Forecasting Capability
        has_date = "DATE" in available_fields
        has_dynamic_numeric = any(
            canonical in (EXTENDED_CLINICAL_FEATURES | {"OTHER"})
            and source in profile.get("columns", {})
            and profile["columns"][source].get("is_numeric", False)
            for source, canonical in canonical_mapping.items()
        )
        has_measure = bool(set(available_fields).intersection({"QUANTITY", "DRUG", "PATIENT_ID"})) or has_dynamic_numeric
        if has_date and has_measure and row_count >= 5:
            capabilities["trend"] = {
                "feasible": True,
                "confidence": 0.95,
                "primary_date_col": canonical_to_source["DATE"][0],
                "models": ["Prophet", "ExponentialSmoothing (ETS)", "ARIMA", "LinearTrend"],
                "description": "Temporal trend evaluation, volume forecasting, and seasonal decomposition."
            }
        else:
            reasons = []
            if not has_date: reasons.append("Missing canonical 'DATE' field")
            if row_count < 5: reasons.append(f"Insufficient longitudinal depth ({row_count} rows)")
            capabilities["trend"] = {
                "feasible": False,
                "confidence": 0.0,
                "reason": " / ".join(reasons),
                "description": "Longitudinal forecasting unavailable due to missing temporal dimensions."
            }

        # 2. Cohort & Clustering Capability
        clustering_features = [f for f in available_fields if f in ["AGE", "QUANTITY", "DOSAGE", "DRUG", "GENDER", "REGION", "DIAGNOSIS", "RISK_SCORE"]]
        dynamic_feature_count = sum(
            1 for source, canonical in canonical_mapping.items()
            if canonical in (EXTENDED_CLINICAL_FEATURES | {"OTHER"})
            and source in profile.get("columns", {})
            and self._is_safe_dynamic_profile(profile["columns"][source], row_count)
        )
        if len(clustering_features) + dynamic_feature_count >= 2 and row_count >= 10:
            capabilities["cohort"] = {
                "feasible": True,
                "confidence": 0.92,
                "feature_count": len(clustering_features) + dynamic_feature_count,
                "features": clustering_features + (["OTHER"] if dynamic_feature_count else []),
                "models": ["KMeans", "DBSCAN", "AgglomerativeClustering", "GaussianMixture"],
                "description": "Patient and prescription phenotypic clustering with metric-driven algorithm selection."
            }
        else:
            capabilities["cohort"] = {
                "feasible": False,
                "confidence": 0.0,
                "reason": f"Requires at least 2 cohort features (found {len(clustering_features) + dynamic_feature_count}) and >= 10 records.",
                "description": "Clustering unavailable due to insufficient dimensional features."
            }

        # 3. Anomaly Detection Capability
        has_numeric = bool(set(available_fields).intersection({"AGE", "QUANTITY", "DOSAGE", "RISK_SCORE"})) or any(p.get("is_numeric", False) for p in profile.get("columns", {}).values())
        if has_numeric and row_count >= 10:
            capabilities["anomaly"] = {
                "feasible": True,
                "confidence": 0.90,
                "models": ["IsolationForest", "LocalOutlierFactor (LOF)", "OneClassSVM", "Statistical Z-Score"],
                "description": "Outlier detection for unusual dosing, abnormal prescribing volume, and risk anomalies."
            }
        else:
            capabilities["anomaly"] = {
                "feasible": False,
                "confidence": 0.0,
                "reason": "Requires numeric distributions and >= 10 records.",
                "description": "Anomaly detection unavailable."
            }

        # 4. Risk Prediction Capability
        has_supervised_target = "RISK_SCORE" in available_fields
        if has_supervised_target and row_count >= 20:
            capabilities["risk"] = {
                "feasible": True,
                "mode": "supervised",
                "target_col": canonical_to_source["RISK_SCORE"][0],
                "models": ["XGBoost", "RandomForest", "GradientBoosting", "LogisticRegression"],
                "description": "Supervised clinical risk stratification with objective cross-validation."
            }
        elif len(clustering_features) + dynamic_feature_count >= 1 and row_count >= 10:
            capabilities["risk"] = {
                "feasible": True,
                "mode": "unsupervised_composite",
                "models": ["Multi-Factor Risk Index", "Isolation Risk Scorer"],
                "description": "Unsupervised composite risk index calculated from clinical dimensions (no explicit target label)."
            }
        else:
            capabilities["risk"] = {
                "feasible": False,
                "confidence": 0.0,
                "reason": "Insufficient features or sample size for risk stratification.",
                "description": "Risk prediction unavailable."
            }

        # 5. Co-Prescribing & Pattern Analysis
        has_patient = "PATIENT_ID" in available_fields
        has_drug = "DRUG" in available_fields
        if (has_patient and has_drug and row_count >= 10) or (has_drug and row_count >= 20):
            capabilities["pattern"] = {
                "feasible": True,
                "confidence": 0.88,
                "models": ["Apriori Association Rules", "FP-Growth", "Co-occurrence Matrix"],
                "description": "Polypharmacy interaction patterns, frequent itemsets, and sequential prescribing rules."
            }
        else:
            capabilities["pattern"] = {
                "feasible": False,
                "confidence": 0.0,
                "reason": "Requires DRUG and PATIENT_ID fields for association rule mining.",
                "description": "Co-prescribing pattern analysis unavailable."
            }

        feasible_count = sum(1 for c in capabilities.values() if c.get("feasible", False))

        return {
            "available_canonical_fields": available_fields,
            "missing_canonical_fields": missing_fields,
            "canonical_to_source_mapping": canonical_to_source,
            "quality_warnings": quality_warnings,
            "capabilities": capabilities,
            "feasible_analysis_count": feasible_count,
            "total_supported_analyses": len(capabilities)
        }

    @staticmethod
    def _is_safe_dynamic_profile(column_profile: Dict[str, Any], row_count: int) -> bool:
        if column_profile.get("is_date") or column_profile.get("unique_count", 0) <= 1:
            return False
        if column_profile.get("is_numeric"):
            return True
        unique_count = column_profile.get("unique_count", 0)
        return 2 <= unique_count <= min(50, max(10, int(max(row_count, 1) * 0.2)))



