"""
Orchestrator & AI Supervisor Planner Module
Plans tool execution based on intent + capability matrix, executes independent tools concurrently,
and handles dependency chains.
"""

import asyncio
import time
import concurrent.futures
import pandas as pd
from typing import Dict, Any, List, Optional, Callable

from tools.tool_registry import ToolRegistry
# Removed internal import


class AgentOrchestrator:
    """
    AI Supervisor / Planner & Execution Orchestrator.
    """

    def __init__(self, registry: Optional[ToolRegistry] = None):
        self.registry = registry or ToolRegistry()
        self.capability_evaluator = CapabilityMatrix()

    def plan_execution(
        self,
        query: str,
        capabilities_report: Dict[str, Any]
    ) -> Dict[str, Any]:
        """
        Creates an intelligent execution plan based on user intent and dataset capabilities.
        """
        q_lower = query.lower() if query else ""
        caps = capabilities_report.get("capabilities", {})

        # Intent detection
        selected_tools = []
        if not q_lower or any(w in q_lower for w in ["all", "comprehensive", "full", "complete", "everything", "analyze"]):
            # Run all feasible tools
            for t_name in ["trend", "cohort", "risk", "anomaly", "pattern"]:
                if caps.get(t_name, {}).get("feasible", False):
                    selected_tools.append(t_name)
        else:
            if any(w in q_lower for w in ["trend", "forecast", "future", "longitudinal", "time", "prediction", "growth"]):
                if caps.get("trend", {}).get("feasible", False): selected_tools.append("trend")
            if any(w in q_lower for w in ["cohort", "cluster", "segment", "group", "phenotype"]):
                if caps.get("cohort", {}).get("feasible", False): selected_tools.append("cohort")
            if any(w in q_lower for w in ["risk", "hazard", "severity", "high risk", "adverse"]):
                if caps.get("risk", {}).get("feasible", False): selected_tools.append("risk")
            if any(w in q_lower for w in ["anomaly", "outlier", "unusual", "abnormal", "fraud", "deviation"]):
                if caps.get("anomaly", {}).get("feasible", False): selected_tools.append("anomaly")
            if any(w in q_lower for w in ["pattern", "interaction", "co-prescrib", "polypharmacy", "association", "combination"]):
                if caps.get("pattern", {}).get("feasible", False): selected_tools.append("pattern")

        # Fallback: if no specific intent matched, include all feasible tools
        if not selected_tools:
            selected_tools = [t for t, c in caps.items() if c.get("feasible", False)]

        # Define dependency stages (Independent tools in Stage 1, dependent tools in Stage 2)
        stage_1_tools = [t for t in selected_tools if t in ["trend", "cohort", "risk", "anomaly"]]
        stage_2_tools = [t for t in selected_tools if t not in stage_1_tools]

        return {
            "query": query,
            "selected_tools": selected_tools,
            "execution_stages": [
                {"stage": 1, "type": "concurrent_independent", "tools": stage_1_tools},
                {"stage": 2, "type": "dependent_sequential", "tools": stage_2_tools}
            ],
            "total_tools": len(selected_tools)
        }

    def execute_plan(
        self,
        df: pd.DataFrame,
        canonical_map: Dict[str, str],
        plan: Dict[str, Any],
        progress_callback: Optional[Callable[[str, Dict[str, Any]], None]] = None
    ) -> Dict[str, Any]:
        """
        Executes tools in parallel according to the plan with real-time event notifications.
        """
        start_overall = time.time()
        results: Dict[str, Any] = {}

        stages = plan.get("execution_stages", [])

        for stage_info in stages:
            tools_to_run = stage_info.get("tools", [])
            if not tools_to_run:
                continue

            if stage_info.get("type") == "concurrent_independent" and len(tools_to_run) > 1:
                # Concurrent Execution via ThreadPool
                with concurrent.futures.ThreadPoolExecutor(max_workers=min(4, len(tools_to_run))) as executor:
                    future_to_tool = {}
                    for t_name in tools_to_run:
                        if progress_callback:
                            progress_callback("tool_started", {"tool": t_name})
                        f = executor.submit(self.registry.execute_tool, t_name, df, canonical_map)
                        future_to_tool[f] = t_name

                    for f in concurrent.futures.as_completed(future_to_tool):
                        t_name = future_to_tool[f]
                        try:
                            res = f.result()
                            results[t_name] = res
                            if progress_callback:
                                progress_callback("tool_completed", {"tool": t_name, "status": res.get("status", "success"), "winner_model": res.get("model", "")})
                        except Exception as e:
                            results[t_name] = {
                                "tool": t_name,
                                "model": "Failed",
                                "status": "error",
                                "warnings": [f"Execution error in {t_name}: {str(e)}"]
                            }
                            if progress_callback:
                                progress_callback("tool_completed", {"tool": t_name, "status": "error", "error": str(e)})
            else:
                # Sequential Execution
                for t_name in tools_to_run:
                    if progress_callback:
                        progress_callback("tool_started", {"tool": t_name})
                    res = self.registry.execute_tool(t_name, df, canonical_map, prior_results=results)
                    results[t_name] = res
                    if progress_callback:
                        progress_callback("tool_completed", {"tool": t_name, "status": res.get("status", "success"), "winner_model": res.get("model", "")})

        total_duration = round((time.time() - start_overall) * 1000, 2)

        return {
            "execution_plan": plan,
            "tool_results": results,
            "total_duration_ms": total_duration,
            "executed_tool_count": len(results)
        }


